// Welcome email composer — first touch on Contact, brochure attached.
function ldWelEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function ldWelFirstName(full) {
  var n = String(full || '').trim();
  if (!n) return '';
  return n.split(/\s+/)[0];
}
function ldWelTemplates(l, lang) {
  var name = ldWelFirstName(l.full_name) || (lang === 'EN' ? 'there' : '');
  var greet = lang === 'EN'
    ? ('Dear ' + (name === 'there' ? 'Owner' : name) + ',')
    : ('Αγαπητέ/ή' + (name ? (' ' + name) : '') + ',');
  var subject = lang === 'EN'
    ? 'Welcome to Elysian Properties'
    : 'Καλωσήρθατε στην Elysian Properties';
  var body = lang === 'EN'
    ? (greet + '\n\n'
      + 'Thank you for your interest in property management with Elysian Properties.\n\n'
      + 'Please find attached our company brochure with the management packages we offer '
      + '(Essential, Signature and Elite) and the hospitality services behind them — '
      + 'dynamic pricing, 24/7 guest support, professional cleaning and transparent pass-through costs.\n\n'
      + 'We would be glad to schedule a short call to discuss your property and the right package.\n\n'
      + 'Kind regards,\n'
      + 'Elysian Properties\n'
      + '+30 210 260 2749\n'
      + 'info@elysianproperties.eu\n'
      + 'elysianproperties.eu')
    : (greet + '\n\n'
      + 'Σας ευχαριστούμε για το ενδιαφέρον σας για τη διαχείριση του ακινήτου σας με την Elysian Properties.\n\n'
      + 'Επισυνάπτουμε το εταιρικό μας brochure με τα πακέτα διαχείρισης (Essential, Signature και Elite) '
      + 'και τις υπηρεσίες φιλοξενίας που προσφέρουμε — δυναμική τιμολόγηση, 24/7 εξυπηρέτηση επισκεπτών, '
      + 'επαγγελματική καθαριότητα και διαφανές μοντέλο κόστους χωρίς markup.\n\n'
      + 'Θα χαρούμε να κανονίσουμε μια σύντομη κλήση για να δούμε μαζί τις ανάγκες του ακινήτου σας.\n\n'
      + 'Με εκτίμηση,\n'
      + 'Elysian Properties\n'
      + '+30 210 260 2749\n'
      + 'info@elysianproperties.eu\n'
      + 'elysianproperties.eu');
  return { subject: subject, body: body };
}
function ldWelBuildHtml(text) {
  var paras = String(text || '').split(/\n\n+/).map(function (p) {
    return '<p style="margin:0 0 12px 0;font-size:13.5px;line-height:1.55;color:#333">'
      + ldWelEsc(p).replace(/\n/g, '<br>') + '</p>';
  }).join('');
  return ''
    + '<div style="margin:0;padding:0;background:#f4f4f2">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f2"><tr><td align="center" style="padding:20px 8px">'
    + '<table role="presentation" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border-radius:8px;overflow:hidden;font-family:Helvetica,Arial,sans-serif;color:#1a1a1a">'
    + '<tr><td style="padding:18px 24px 12px 24px;border-bottom:3px solid #0F1E2E">'
    + '<div style="font-size:19px;font-weight:700;color:#0F1E2E;letter-spacing:.02em">ELYSIAN</div>'
    + '<div style="font-size:11px;color:#C9A84C;letter-spacing:.12em;text-transform:uppercase;margin-top:2px">Properties Management</div>'
    + '</td></tr>'
    + '<tr><td style="padding:22px 24px 8px 24px">' + paras + '</td></tr>'
    + '<tr><td style="background:#f9f9f7;padding:12px 24px;font-size:10px;color:#999">'
    + 'Elysian Properties · Athens · Thessaloniki · Patra · elysianproperties.eu'
    + '</td></tr>'
    + '</table></td></tr></table></div>';
}
function ldWelClose() {
  var ov = document.getElementById('ld-wel-ov');
  if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
  window._ldWel = null;
}
function ldWelApplyLang() {
  var st = window._ldWel; if (!st) return;
  var lang = (document.getElementById('ld-wel-lang') || {}).value || 'GR';
  var t = ldWelTemplates(st.lead, lang);
  var sub = document.getElementById('ld-wel-subj');
  var bod = document.getElementById('ld-wel-body');
  if (sub) sub.value = t.subject;
  if (bod) bod.value = t.body;
  // Swap the attached brochure to match the chosen language.
  (async function () {
    if (typeof st.loadBrochure !== 'function') return;
    var b = await st.loadBrochure(lang);
    st.brochure = b;
    var att = document.getElementById('ld-wel-attach');
    var meta = document.getElementById('ld-wel-att-meta');
    if (att) { att.disabled = !b; att.checked = !!b; }
    if (meta) {
      meta.textContent = b
        ? (b.filename + ' · ' + (b.size ? ((b.size / 1024).toFixed(0) + ' KB') : 'attached') + ' · ' + lang)
        : 'Brochure not available for ' + lang;
    }
  })();
}
window.ldWelcome = async function (id) {
  var l = lead(id);
  if (!l) return;
  if (!l.email) { toast('This lead has no email address.', 'err'); return; }
  ldWelClose();
  var cfg = { configured: false };
  try {
    if (typeof _emailStatus === 'function') cfg = await _emailStatus(true);
    else {
      var r = await fetch('/api/email/status');
      cfg = r.ok ? await r.json() : { configured: false };
    }
  } catch (e) { cfg = { configured: false }; }
  var lang0 = 'GR';
  async function loadBrochure(lang) {
    var key = lang === 'EN' ? 'brochure-en' : 'brochure-gr';
    var brochure = null;
    try {
      var ar = await fetch('/api/lead-assets/' + key);
      var aj = await ar.json();
      if (ar.ok && aj.asset && aj.asset.data) {
        brochure = {
          filename: aj.asset.filename || ('Elysian-Properties-Management-Brochure-' + lang + '.pdf'),
          mime: aj.asset.mime || 'application/pdf',
          data: aj.asset.data,
          size: aj.asset.size || 0,
          version: aj.asset.version || 1,
          key: key
        };
      }
    } catch (e) { brochure = null; }
    if (!brochure) {
      try {
        var file = lang === 'EN'
          ? '/assets/elysian-management-brochure-en.pdf'
          : '/assets/elysian-management-brochure-gr.pdf';
        var fr = await fetch(file);
        if (fr.ok) {
          var buf = await fr.arrayBuffer();
          var bytes = new Uint8Array(buf);
          var bin = '';
          for (var i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
          brochure = {
            filename: 'Elysian-Properties-Management-Brochure-' + lang + '.pdf',
            mime: 'application/pdf',
            data: btoa(bin),
            size: bytes.length,
            version: 0,
            key: key
          };
        }
      } catch (e2) { brochure = null; }
    }
    return brochure;
  }
  var brochure = await loadBrochure(lang0);
  var t0 = ldWelTemplates(l, lang0);
  window._ldWel = { lead: l, brochure: brochure, cfg: cfg, loadBrochure: loadBrochure };
  var sizeLbl = brochure
    ? (brochure.filename + ' · ' + (brochure.size ? ((brochure.size / 1024).toFixed(0) + ' KB') : 'attached'))
    : 'Brochure not available — upload via lead assets or redeploy with assets/elysian-management-brochure.pdf';
  var ov = document.createElement('div');
  ov.id = 'ld-wel-ov';
  ov.innerHTML = ''
    + '<div class="ld-wel" role="dialog" aria-label="Welcome email">'
    + '<div class="ld-wel-h"><h3>Welcome email</h3>'
    + '<button type="button" class="btn sm" onclick="ldWelClose()">✕</button></div>'
    + '<div class="ld-wel-b">'
    + '<div class="ld-wel-row">'
    + '<div style="flex:1;min-width:160px"><label>To</label><input id="ld-wel-to" value="' + ldWelEsc(l.email) + '"/></div>'
    + '<div style="width:110px"><label>Language</label><select id="ld-wel-lang" onchange="ldWelApplyLang()">'
    + '<option value="GR" selected>Greek</option><option value="EN">English</option></select></div>'
    + '</div>'
    + '<div><label>Subject</label><input id="ld-wel-subj" value="' + ldWelEsc(t0.subject) + '"/></div>'
    + '<div><label>Message</label><textarea id="ld-wel-body">' + ldWelEsc(t0.body) + '</textarea></div>'
    + '<div class="ld-wel-att"><label style="display:flex;align-items:center;gap:8px;margin:0;color:inherit;font-size:12px">'
    + '<input type="checkbox" id="ld-wel-attach"' + (brochure ? ' checked' : ' disabled') + '/>'
    + 'Attach company brochure — services &amp; packages (matches language)</label>'
    + '<div id="ld-wel-att-meta" style="margin-top:6px;font-size:11.5px;color:var(--tx3,#888)">' + ldWelEsc(sizeLbl) + '</div></div>'
    + (!cfg.configured ? '<div style="font-size:12px;color:#D97706">Email SMTP is not configured on the server — Send will be unavailable until SMTP_* is set.</div>' : '')
    + '</div>'
    + '<div class="ld-wel-f">'
    + '<button type="button" class="btn sm" onclick="ldWelClose()">Cancel</button>'
    + '<button type="button" class="btn sm primary" id="ld-wel-send" onclick="ldWelSend()"'
    + (!cfg.configured ? ' disabled' : '') + '>Send welcome email</button>'
    + '</div></div>';
  ov.addEventListener('click', function (ev) { if (ev.target === ov) ldWelClose(); });
  document.body.appendChild(ov);
};
window.ldWelClose = ldWelClose;
window.ldWelApplyLang = ldWelApplyLang;
window.ldWelSend = async function () {
  var st = window._ldWel; if (!st || !st.lead) return;
  var to = String((document.getElementById('ld-wel-to') || {}).value || '').trim();
  var subject = String((document.getElementById('ld-wel-subj') || {}).value || '').trim();
  var body = String((document.getElementById('ld-wel-body') || {}).value || '').trim();
  var attach = !!(document.getElementById('ld-wel-attach') || {}).checked;
  if (!to) { toast('Add a recipient email.', 'err'); return; }
  if (!subject) { toast('Add a subject.', 'err'); return; }
  if (!body) { toast('The message is empty.', 'err'); return; }
  var btn = document.getElementById('ld-wel-send');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
  var attachments = [];
  if (attach && st.brochure && st.brochure.data) {
    attachments.push({
      filename: st.brochure.filename,
      contentType: st.brochure.mime || 'application/pdf',
      contentBase64: st.brochure.data
    });
  }
  try {
    var r = await fetch('/api/email/send', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: to,
        subject: subject,
        text: body,
        html: ldWelBuildHtml(body),
        attachments: attachments
      })
    });
    var j = await r.json().catch(function () { return {}; });
    if (!r.ok) throw new Error(j.error || ('Send failed (' + r.status + ')'));
    var note = 'Welcome email → ' + to + (attachments.length ? ' (+ brochure)' : '');
    var patch = { emailSent: note, by: who() };
    // First touch: advance Contact stage when still new / to_contact.
    if (st.lead.stage === 'new' || st.lead.stage === 'to_contact') patch.stage = 'contacted';
    await jsend('/api/leads/' + st.lead.id, 'PATCH', patch);
    toast('Welcome email sent.');
    ldWelClose();
    reload(true);
  } catch (e) {
    toast(e.message || String(e), 'err');
    if (btn) { btn.disabled = false; btn.textContent = 'Send welcome email'; }
  }
};

